{"record_type":"obligation_result","obligation_index":0,"status":"items","reason_code":null,"items":[{"text":"这对我们来说是好事，希望他们把HVLP铜箔做出来。","semantic_type":"opinion","statement_role":"claim","speech_role":"statement","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":1,"status":"items","reason_code":null,"items":[{"text":"请问能听到吗？","semantic_type":"fact","statement_role":"question","speech_role":"question","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"},{"text":"可以，您讲。","semantic_type":"fact","statement_role":"answer","speech_role":"answer","perspective":"quoted_other","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":2,"status":"items","reason_code":null,"items":[{"text":"我这边想问一下。","semantic_type":"opinion","statement_role":"question","speech_role":"question","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":3,"status":"items","reason_code":null,"items":[{"text":"您刚刚说跟HVLP陪跑，不知道现在良品率到了什么水平？","semantic_type":"fact","statement_role":"question","speech_role":"question","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":4,"status":"items","reason_code":null,"items":[{"text":"用咱们的设备，以及咱们预估最后能做到什么样的良品率？","semantic_type":"fact","statement_role":"question","speech_role":"question","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":5,"status":"items","reason_code":null,"items":[{"text":"这会影响设备需求。","semantic_type":"fact","statement_role":"claim","speech_role":"statement","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":6,"status":"items","reason_code":null,"items":[{"text":"现在HVLP1或2很多厂家也能做，","semantic_type":"fact","statement_role":"claim","speech_role":"statement","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":7,"status":"items","reason_code":null,"items":[{"text":"但良品率确实不高。","semantic_type":"fact","statement_role":"claim","speech_role":"statement","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":8,"status":"items","reason_code":null,"items":[{"text":"他们对设备厂商保密，不给我们看。","semantic_type":"fact","statement_role":"claim","speech_role":"statement","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":9,"status":"items","reason_code":null,"items":[{"text":"我预估可能就40%左右。","semantic_type":"forecast","statement_role":"claim","speech_role":"statement","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":10,"status":"items","reason_code":null,"items":[{"text":"这还是1到2？","semantic_type":"fact","statement_role":"question","speech_role":"question","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":11,"status":"items","reason_code":null,"items":[{"text":"良品率不高。","semantic_type":"fact","statement_role":"claim","speech_role":"statement","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":12,"status":"items","reason_code":null,"items":[{"text":"您刚说现在主要做1到2，1到2和3到4是上台阶的难度吗？","semantic_type":"fact","statement_role":"question","speech_role":"question","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":13,"status":"items","reason_code":null,"items":[{"text":"大家会逐个突破？","semantic_type":"fact","statement_role":"question","speech_role":"question","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":14,"status":"items","reason_code":null,"items":[{"text":"1到2相对简单一点，表面粗糙度要求没那么高。","semantic_type":"fact","statement_role":"claim","speech_role":"statement","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":15,"status":"items","reason_code":null,"items":[{"text":"3到4已经要求小于等于一微米的表面粗糙度，难度越大，良品率肯定会越来越低。","semantic_type":"fact","statement_role":"claim","speech_role":"statement","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":16,"status":"items","reason_code":null,"items":[{"text":"像铜冠一个月也就出一百多吨，他们年标箔产量5.5万吨，一个月只做了一百多吨，这个数据很惊人。","semantic_type":"fact","statement_role":"claim","speech_role":"statement","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":17,"status":"items","reason_code":null,"items":[{"text":"您觉得良品率低是设备问题还是工艺问题？","semantic_type":"fact","statement_role":"question","speech_role":"question","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":18,"status":"items","reason_code":null,"items":[{"text":"设备端能配套改进吗？","semantic_type":"fact","statement_role":"question","speech_role":"question","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":19,"status":"items","reason_code":null,"items":[{"text":"我认为设备目前加工精度和控制精度已经做到行业领先，","semantic_type":"fact","statement_role":"claim","speech_role":"statement","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":20,"status":"items","reason_code":null,"items":[{"text":"那么大概率跟工艺挂钩。","semantic_type":"fact","statement_role":"claim","speech_role":"statement","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":21,"status":"items","reason_code":null,"items":[{"text":"之前跟铜冠总工探讨过，他说工艺和设备是64开，","semantic_type":"fact","statement_role":"claim","speech_role":"statement","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":22,"status":"items","reason_code":null,"items":[{"text":"工艺占大头，","semantic_type":"fact","statement_role":"claim","speech_role":"statement","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
{"record_type":"obligation_result","obligation_index":23,"status":"items","reason_code":null,"items":[{"text":"设备只是配套，","semantic_type":"fact","statement_role":"claim","speech_role":"statement","perspective":"source_explicit","polarity":"affirmed","evidence_selector":"slot"}]}
